    mc = next((c for c in range(w)
               if all(grid[r][c] == marker for r in range(h))), None)

    counts = {}
    for row in grid:
        for x in row:
            if x != marker:
                counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    colors = [x for x in counts if x != bg]
    if not colors:
        return out
    color = max(colors, key=lambda x: counts[x])
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == color]

    if mc is not None:
        # Move the object to sit next to the marker column.
        shift = mc + 1 - min(c for r, c in cells)
        moved = [(r, c + shift) for r, c in cells]
        for r, c in cells:
            out[r][c] = bg
        for r, c in moved:
            if 0 <= c < w:
                out[r][c] = color
        sep = max(c for r, c in moved) + 1
        if 0 <= sep < w:
            for r in range(h):
                out[r][sep] = 8

    elif mr is not None:
        # The object already lies just below the marker row; add a line after it.
        sep = max(r for r, c in cells) + 1
        if 0 <= sep < h:
            out[sep] = [8] * w

    return out
